float sdBox( vec3 p, vec3 b ) {
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

vec3 erot(vec3 p, vec3 ax, float ro) {
    return mix(dot(p,ax)*ax,p,cos(ro))+sin(ro)*cross(ax,p);
}

vec2 edge(vec2 p) {
    vec2 p2 = abs(p);
    if (p2.x > p2.y) return vec2((p.x < 0.) ? -1. : 1., 0.);
    else             return vec2(0., (p.y < 0.) ? -1. : 1.);
}

#define FK(k) floatBitsToInt(cos(k))^floatBitsToInt(k)
float hash(float a, float b) {
    int x = FK(a), y = FK(b);
    return float((x*x+y)*(y*y-x)-x)/2.14e9;
}

float building3D(vec3 p, float height) {
    float me = sdBox(p, vec3(0.3, 0.3, height));
    return me;
}

float scene(vec3 p) {
    vec2 center = floor(p.xy) + .5;
    vec2 neighbour = center + edge(p.xy - center);
    float hs = round(hash(hash(center.x, center.y), 0.) * 4.) / 4. - 0.125;
    float me = building3D(p - vec3(center, 0.), 1. + hs);
    float next = building3D(p - vec3(neighbour, 0), 2.);
    float flr = step(0., p.z);
    float buildings = min(next, me);
    return min(flr, buildings);
}

vec3 norm(vec3 p) {
    mat3 k = mat3(p,p,p)-mat3(0.01);
    return normalize(scene(p) - vec3(scene(k[0]),scene(k[1]),scene(k[2])));
}

#define RAY_AMT 200

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec2 mouse = (iMouse.xy-0.5*iResolution.xy)/iResolution.y;
    vec3 cam = normalize(vec3(1.5,uv));
    vec3 init = vec3(-7,0,1.);

    float yrot = .2;
    float zrot = iTime *.02;

    if (iMouse.z > 0.) {
        yrot = clamp(1.-4.*mouse.y,-0.,3.14/2.);
        zrot = 4.*mouse.x;
    }

    cam = erot(cam,vec3(0,1,0),yrot);
    init = erot(init,vec3(0,1,0),yrot);
    cam = erot(cam,vec3(0,0,1),zrot);
    init = erot(init,vec3(0,0,1),zrot);
    init.y += iTime * .5;

    vec3 p = init;
    bool hit = false;
    float rayDist = 0.;
    for (int i = 0; i < RAY_AMT && !hit; i++) {
        float dist = scene(p);
        hit = dist*dist < 1e-6;
        p += dist*cam;
        rayDist = float(RAY_AMT - i)/float(RAY_AMT);
        if(distance(p,init)>50.)break;
    }
    vec3 n = norm(p);
    vec3 r = reflect(cam, n);
    float colVal = length(sin(r*2.)*.5+.5)/sqrt(3.);
    colVal = colVal*.1 + pow(colVal, 6.);

    vec4 col = vec4(colVal);
    vec3 rep = vec3(0.1, 0.1, 0.25);

    if (distance(n, vec3(0., 0., 1.)) > 0.1) {
        vec3 center = rep*round(p/rep);
        float hs = smoothstep(0.3, 0.95, hash(hash(center.x, center.y), center.z) * 0.5 + .5) + .05;
        col = sdBox(p - center, vec3(.02,.03,.08)) < 0. ? vec4(1.) * (.5 + colVal * 0.5) * hs : col;
    }

    fragColor = hit ? col : vec4(0.03);
    fragColor *= smoothstep(0.5, 2., p.z);

    fragColor = sqrt(fragColor);

    fragColor = max(fragColor, vec4(1. - rayDist) * 0.6);

    fragColor.xyz *= vec3(0.8, 0.8, 1.);
}
